#!/usr/bin/env python3
from __future__ import annotations
import argparse,json
from html import escape
from pathlib import Path
def main():
 p=argparse.ArgumentParser();p.add_argument('--fixture',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();f=json.loads(a.fixture.read_text());cards=[]
 for c in f['claims']['claims']:
  cards.append(f'<section data-id="{escape(c["claim_id"],quote=True)}"><p><b>{escape(c["kind"])}</b> {escape(json.dumps(c["value"],ensure_ascii=False))}<br>Literal: <q>{escape(c["evidence"]["text"])}</q><br>OCR: {c["requires_ocr"]}; orientación: {c["requires_orientation"]}</p><label>Decisión<select><option value="">pendiente</option><option value="approved">approved</option><option value="rejected">rejected</option></select></label><label>Motivo<input maxlength="160"></label></section>')
 data=json.dumps(f['claims']['claims'],ensure_ascii=False).replace('</','<\\/');script=r'''<script id="claims" type="application/json">DATA</script><script>const claims=JSON.parse(document.getElementById('claims').textContent),by=new Map(claims.map(c=>[c.claim_id,c])); function buildExport(){const reviewer=document.getElementById('reviewer').value.trim();if(!reviewer)throw Error('Falta revisor');const records=[];document.querySelectorAll('section').forEach(s=>{const d=s.querySelector('select').value;if(!d)throw Error('Quedan claims pendientes');records.push({claim:by.get(s.dataset.id),decision:d,reason:s.querySelector('input').value.trim()||null,reviewer,reviewed_at_utc:new Date().toISOString()});});return JSON.stringify({schema_version:'1.0',contract_version:'visual-reviewed-claim-set-v1',fixture_id:'FIXTURE',fixture_role:'development',review_status:'complete',records},null,2)+'\n';} document.getElementById('export').onclick=()=>{try{const u=URL.createObjectURL(new Blob([buildExport()],{type:'application/json'})),l=document.createElement('a');l.href=u;l.download='h11-reviewed-claims.json';l.click();setTimeout(()=>URL.revokeObjectURL(u),1000);document.getElementById('status').textContent='Exportado';}catch(e){document.getElementById('status').textContent=e.message;}}; window.claimReviewFormTest=()=>({claims:claims.length,sections:document.querySelectorAll('section').length,selects:document.querySelectorAll('select').length,inputs:document.querySelectorAll('section input').length,buildExportType:typeof buildExport});document.documentElement.dataset.ready='true';document.getElementById('status').textContent='Formulario cargado: '+claims.length+' claims.';if(new URLSearchParams(location.search).get('autotest')==='1'){document.querySelectorAll('select').forEach(x=>x.value='approved');document.querySelectorAll('section input').forEach(x=>x.value='autotest');let result;try{const exported=JSON.parse(buildExport());result={ok:true,records:exported.records.length,approved:exported.records.filter(x=>x.decision==='approved').length,selects:document.querySelectorAll('select').length};}catch(e){result={ok:false,error:e.message};}document.getElementById('status').textContent='AUTOTEST '+JSON.stringify(result);fetch('/__form_autotest__?form=claims&result='+encodeURIComponent(JSON.stringify(result))).catch(()=>{});}</script>'''.replace('DATA',data).replace('FIXTURE',f['fixture_id']);html='<!doctype html><html lang="es" data-ready="false"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Revisión claims H11</title><style>body{font:16px system-ui;max-width:900px;margin:auto;padding:2rem;background:#f4f1e8}section{background:white;border-left:4px solid #1f6f54;padding:1rem;margin:1rem 0}label{display:block;margin:.5rem 0}select,input{font:inherit;width:100%}</style></head><body><h1>Revisión de claims H11</h1><p>Aprueba solo afirmaciones atómicas, literales y visualmente comprobables. Rechaza relaciones egocéntricas mientras no exista orientación comparable.</p><label>Revisor <input id="reviewer" value="marcos"></label><button id="export" type="button">Exportar claims revisados</button> <span id="status">Inicializando formulario…</span>'+''.join(cards)+script+'</body></html>';a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(html,encoding='utf-8');print(json.dumps({'claims':len(cards),'output':str(a.output)}));return 0
if __name__=='__main__':raise SystemExit(main())
